+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * A filter understood by {@link CustomerRepository}.
+ *
+ * <p>A customer matches when every whitespace-separated term of {@code name}
+ * appears, ignoring case and accents, in its first or last name, and when its
+ * status is one of {@code statuses} (an empty set allows every status).
+ *
+ * @param name     free-text name filter; may be blank
+ * @param statuses statuses to allow; empty means all
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    private static final Pattern MARKS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name.strip();
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of()
+                : Set.copyOf(EnumSet.copyOf(statuses));
+    }
+
+    public boolean isEmpty() {
+        return terms().isEmpty() && statuses.isEmpty();
+    }
+
+    /** The normalized search terms of the name filter. */
+    public List<String> terms() {
+        String normalized = normalize(name);
+        if (normalized.isBlank()) {
+            return List.of();
+        }
+        return Arrays.asList(normalized.strip().split("\\s+"));
+    }
+
+    /** Builds the predicate the repository applies to each row. */
+    public Predicate<Customer> toPredicate() {
+        List<String> terms = terms();
+        Set<CustomerStatus> allowed = statuses;
+        return customer -> {
+            if (!allowed.isEmpty() && !allowed.contains(customer.status())) {
+                return false;
+            }
+            if (terms.isEmpty()) {
+                return true;
+            }
+            String first = normalize(customer.firstName());
+            String last = normalize(customer.lastName());
+            return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
+        };
+    }
+
+    /** Lower-cases and strips accents, so that {@code Mäkinen} becomes {@code makinen}. */
+    static String normalize(String text) {
+        if (text == null) {
+            return "";
+        }
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFKD);
+        return MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
